/// Runs the commands this module owns; None for the others.
pub fn dispatch(s: &mut Session, cid: &str, p: &Value) -> Option<Result<Value, String>> {
    Some(match cid {
        "inspect" => Ok(crate::inspect::inspect(s)),
        "elements" => view::cmd_elements(s, p),
        "schedule" => schedule::cmd_schedule(s, p),
        "filter_selection" => schedule::cmd_filter_selection(s, p),
        "select_by_id" => notes::cmd_select_by_id(s, p),
        "ids_of" => notes::cmd_ids_of(s, p),
        "measure" => notes::cmd_measure(s, p),
        _ => return None,
    })
}

/// The model rules this module owns, checked after every command.
pub fn check(pr: &crate::project::Project) -> Result<(), String> {
    let _ = pr;
    Ok(())
}
//! `elements`: each element as the project file holds it, with its id and what is worked out of
//! it (a wall's length, a room's area, a door's place…), each category by the module that knows it.

use super::common::{self, Ctx};
use crate::json::Value;
use crate::project::Project;
use crate::session::Session;

/// An element as `elements` shows it: its fields as stored (what it points at by GUID), its
/// `id`, and its derived values. None for an id the project hasn't.
pub fn element_view(cx: &Ctx, id: u64) -> Option<Value> {
    let pr = cx.pr;
    let e = pr.el(id)?;
    let mut x = e.clone();
    x.set("id", Value::u(id));
    match common::category(e) {
        "wall" | "room" | "roomseparator" => super::walls::view(cx, id, &mut x),
        "floor" | "ceiling" | "roof" | "shaft" | "mass" => super::slabs::view(cx, id, &mut x),
        "door" | "window" | "component" | "column" | "structuralcolumn" | "footing" | "beam"
        | "stripfooting" | "pipe" | "duct" | "conduit" | "cabletray" | "wire" | "downconductor"
        | "groundconductor" | "cable" | "rebar" | "stair" | "ramp" | "railing" => super::parts::view(cx, id, &mut x),
        "pointcloud" => crate::cloud::element_view(pr, &mut x),
        _ => super::notes::view(cx, id, &mut x),
    }
    Some(x)
}

/// One element's view, for a caller without a context of its own.
pub fn view_of(pr: &Project, id: u64) -> Option<Value> {
    let cx = Ctx::new(pr);
    element_view(&cx, id)
}

/// A category as `elements` (and other readers) take one: in any case, its words run together or
/// apart (`structural columns`, `room_separator`), plural or not (`walls`, `masses`).
pub fn category_matches(query: &str, cat: &str) -> bool {
    let q: String = query.chars().filter(|c| c.is_alphanumeric()).flat_map(|c| c.to_lowercase()).collect();
    if q.is_empty() {
        return false;
    }
    if q == cat {
        return true;
    }
    let plural = if cat.ends_with('s') { format!("{}es", cat) } else { format!("{}s", cat) };
    if q == plural {
        return true;
    }
    !cat.ends_with('s') && q.trim_end_matches('s') == cat
}

fn whole(p: &Value, key: &str) -> Result<Option<u64>, String> {
    match crate::commands::params::get(p, key) {
        None => Ok(None),
        Some(Value::Num(crate::json::Num::U(u))) => Ok(Some(*u)),
        Some(v) => Err(format!("elements: `{}` must be a whole number, got {}", key, v.to_compact())),
    }
}

/// `elements {category?, level?, limit?, offset?}`.
pub fn cmd_elements(s: &Session, p: &Value) -> Result<Value, String> {
    let pr = &s.project;
    let empty = Value::obj();
    let p = if matches!(p, Value::Obj(_)) { p } else { &empty };
    let cat = crate::commands::params::opt_text(p, "elements", "category")?;
    let level = match crate::commands::params::get(p, "level") {
        None => None,
        Some(v) => Some(crate::model::resolve_level(pr, "elements", "level", v)?),
    };
    let limit = whole(p, "limit")?;
    let offset = whole(p, "offset")?.unwrap_or(0);
    let level_guid = level.and_then(|l| pr.guid_of(l));
    let cx = Ctx::new(pr);
    let mut out = Vec::new();
    let mut count = 0u64;
    for (id, e) in &pr.elements {
        if let Some(want) = &cat {
            if !category_matches(want, common::category(e)) {
                continue;
            }
        }
        // what lies outside the page asked for is counted, not worked out (unless its level,
        // which may be derived, decides whether it counts)
        let wanted = |n: u64| n > offset && limit.map(|l| n - offset <= l).unwrap_or(true);
        if level_guid.is_none() {
            count += 1;
            if wanted(count) {
                if let Some(x) = element_view(&cx, *id) {
                    out.push(x);
                }
            }
            continue;
        }
        let x = match element_view(&cx, *id) {
            Some(x) => x,
            None => continue,
        };
        if let Some(g) = &level_guid {
            if common::text(&x, "level") != Some(g.as_str()) {
                continue;
            }
        }
        count += 1;
        if wanted(count) {
            out.push(x);
        }
    }
    let n = out.len();
    Ok(jobj! {"count" => count, "elements" => Value::Arr(out), "returned" => n})
}
//! Lookups the readers share: types, families, materials and levels by the GUIDs elements hold,
//! the context a reading goes through (with room for each module's cache), and rounding.

use crate::json::{Map, Value};
use crate::project::Project;
use std::any::Any;
use std::cell::RefCell;
use std::collections::HashMap;

/// What a reading of the model goes through: the project, and what the modules worked out of it
/// once (each under a key of its own: `rooms`, `roofs`…), so reading many elements doesn't work
/// the same thing out again for each.
pub struct Ctx<'a> {
    pub pr: &'a Project,
    cache: RefCell<HashMap<&'static str, Box<dyn Any>>>,
}

impl<'a> Ctx<'a> {
    pub fn new(pr: &'a Project) -> Ctx<'a> {
        Ctx { pr, cache: RefCell::new(HashMap::new()) }
    }

    /// The value cached under `key`, worked out by `make` the first time (and cloned out: keep
    /// cached values cheap to clone, an `Rc` for anything big).
    pub fn cached<T: Any + Clone>(&self, key: &'static str, make: impl FnOnce() -> T) -> T {
        if let Some(v) = self.cache.borrow().get(key) {
            if let Some(t) = v.downcast_ref::<T>() {
                return t.clone();
            }
        }
        let v = make();
        self.cache.borrow_mut().insert(key, Box::new(v.clone()));
        v
    }
}

/// Rounds to hundredths, as the original rounds the lengths and areas it reports.
pub fn r2(x: f64) -> f64 {
    let v = (x * 100.0).round() / 100.0;
    if v == 0.0 {
        0.0
    } else {
        v
    }
}

/// Rounds to `n` decimals.
pub fn rn(x: f64, n: i32) -> f64 {
    let k = 10f64.powi(n);
    let v = (x * k).round() / k;
    if v == 0.0 {
        0.0
    } else {
        v
    }
}

pub fn num(e: &Value, k: &str) -> Option<f64> {
    e.get(k).and_then(|x| x.as_f64())
}

pub fn text<'v>(e: &'v Value, k: &str) -> Option<&'v str> {
    e.get(k).and_then(|x| x.as_str())
}

pub fn point(e: &Value, k: &str) -> Option<[f64; 2]> {
    let a = e.get(k)?.as_arr()?;
    if a.len() < 2 {
        return None;
    }
    Some([a[0].as_f64()?, a[1].as_f64()?])
}

pub fn points(v: &Value) -> Vec<[f64; 2]> {
    v.as_arr()
        .map(|a| {
            a.iter()
                .filter_map(|p| {
                    let q = p.as_arr()?;
                    Some([q.first()?.as_f64()?, q.get(1)?.as_f64()?])
                })
                .collect()
        })
        .unwrap_or_default()
}

pub fn category(e: &Value) -> &str {
    e.get("category").and_then(|c| c.as_str()).unwrap_or("")
}

// ---------------------------------------------------------------- elements and levels

/// The element a GUID names.
pub fn by_guid<'p>(pr: &'p Project, g: &str) -> Option<(u64, &'p Value)> {
    let id = pr.find_guid(g)?;
    Some((id, pr.el(id)?))
}

/// The element a field of `e` points at by GUID.
pub fn target<'p>(pr: &'p Project, e: &Value, k: &str) -> Option<(u64, &'p Value)> {
    by_guid(pr, text(e, k)?)
}

/// A level's elevation, by its GUID.
pub fn level_elev(pr: &Project, g: &str) -> Option<f64> {
    let (_, l) = by_guid(pr, g)?;
    num(l, "elevation")
}

/// The level above a level (by GUID), the next by elevation.
pub fn level_above(pr: &Project, g: &str) -> Option<u64> {
    let id = pr.find_guid(g)?;
    crate::model::level_above(pr, id)
}

// ---------------------------------------------------------------- types

/// Where a category's types are kept: their key in `types` (under `runs` for a run's), and the
/// library's kind for them.
pub fn type_home(cat: &str) -> Option<(&'static str, bool, &'static str)> {
    Some(match cat {
        "wall" => ("wall", false, "type:wall"),
        "floor" => ("floor", false, "type:floor"),
        "ceiling" => ("ceiling", false, "type:ceiling"),
        "roof" => ("roof", false, "type:roof"),
        "door" => ("door", false, "type:door"),
        "window" => ("window", false, "type:window"),
        "column" => ("column", false, "type:column"),
        "structuralcolumn" => ("structural_column", false, "type:structuralcolumn"),
        "footing" => ("footing", false, "type:footing"),
        "railing" => ("railing", false, "type:railing"),
        "beam" => ("beam", true, "type:beam"),
        "stripfooting" => ("stripfooting", true, "type:stripfooting"),
        "pipe" => ("pipe", true, "type:pipe"),
        "duct" => ("duct", true, "type:duct"),
        "conduit" => ("conduit", true, "type:conduit"),
        "cabletray" => ("cabletray", true, "type:cabletray"),
        "wire" => ("wire", true, "type:wire"),
        "downconductor" => ("downconductor", true, "type:downconductor"),
        "groundconductor" => ("groundconductor", true, "type:groundconductor"),
        "cable" => ("cable", true, "type:cable"),
        _ => return None,
    })
}

/// A category's types, by name.
pub fn types_of<'p>(pr: &'p Project, cat: &str) -> Option<&'p Map> {
    let (key, run, _) = type_home(cat)?;
    let t = pr.section("types")?;
    if run {
        t.get("runs")?.get(key)?.as_obj()
    } else {
        t.get(key)?.as_obj()
    }
}

/// The type a GUID names among a category's types: its name and its definition.
pub fn type_of<'p>(pr: &'p Project, cat: &str, g: &str) -> Option<(String, &'p Value)> {
    let (_, _, kind) = type_home(cat)?;
    let lid = pr.lib_find_guid(g)?;
    let le = pr.library.get(&lid)?;
    if text(le, "kind") != Some(kind) {
        return None;
    }
    let name = text(le, "name")?.to_string();
    let def = types_of(pr, cat)?.get(&name)?;
    Some((name, def))
}

/// The type of an element (by its `type` GUID) as its category keeps them.
pub fn element_type<'p>(pr: &'p Project, e: &Value) -> Option<(String, &'p Value)> {
    type_of(pr, category(e), text(e, "type")?)
}

// ---------------------------------------------------------------- families

/// A family by its GUID: its name and its definition.
pub fn family<'p>(pr: &'p Project, g: &str) -> Option<(String, &'p Value)> {
    let lid = pr.lib_find_guid(g)?;
    let le = pr.library.get(&lid)?;
    if text(le, "kind") != Some("family") {
        return None;
    }
    let name = text(le, "name")?.to_string();
    let def = pr.section("families")?.get(&name)?;
    Some((name, def))
}

/// The family and type names a family type's GUID names (its library entry is `Family: Type`).
pub fn family_type(pr: &Project, family_name: &str, g: &str) -> Option<String> {
    let lid = pr.lib_find_guid(g)?;
    let le = pr.library.get(&lid)?;
    if text(le, "kind") != Some("family-type") {
        return None;
    }
    let name = text(le, "name")?;
    name.strip_prefix(family_name)?.strip_prefix(": ").map(|s| s.to_string())
}

// ---------------------------------------------------------------- materials

/// A material's name, by its GUID.
pub fn material_name(pr: &Project, g: &str) -> Option<String> {
    let lid = pr.lib_find_guid(g)?;
    let le = pr.library.get(&lid)?;
    if text(le, "kind") != Some("material") {
        return None;
    }
    text(le, "name").map(|s| s.to_string())
}

/// A library entry's name by its GUID, of the kind given.
pub fn lib_name_of(pr: &Project, kind: &str, g: &str) -> Option<String> {
    let lid = pr.lib_find_guid(g)?;
    let le = pr.library.get(&lid)?;
    if text(le, "kind") != Some(kind) {
        return None;
    }
    text(le, "name").map(|s| s.to_string())
}

//! Doors, windows, components (and their families' parameters worked out), columns, footings,
//! beams and runs, rebar, stairs, ramps and railings as `elements` shows them.

use crate::json::Value;
use crate::readers::common::{self, Ctx};

/// Adds the derived values of a door, window, component, column, footing, beam, run, rebar,
/// stair, ramp or railing to its view `x`.
pub fn view(cx: &Ctx, id: u64, x: &mut Value) {
    let pr = cx.pr;
    let _ = id;
    if common::type_home(common::category(x)).is_some() && x.get("family").is_none() {
        if let Some((name, _def)) = common::element_type(pr, x) {
            let g = common::text(x, "type").unwrap_or("").to_string();
            x.set("type", Value::Str(name));
            x.set("type_guid", Value::Str(g));
        }
    }
}
//! Walls, rooms and room separators as `elements` shows them: a wall's length, thickness, type and
//! height; a room's boundary worked out of the walls, separators and columns around its point,
//! its area, perimeter, height and volume.

use crate::json::Value;
use crate::readers::common::{self, Ctx};

/// Adds a wall's, room's or room separator's derived values to its view `x` (its stored fields
/// and `id`).
pub fn view(cx: &Ctx, id: u64, x: &mut Value) {
    let pr = cx.pr;
    let _ = id;
    match common::category(x) {
        "wall" => {
            if let Some((name, def)) = common::element_type(pr, x) {
                let t = common::num(def, "thickness").unwrap_or(0.0);
                let g = common::text(x, "type").unwrap_or("").to_string();
                x.set("type", Value::Str(name));
                x.set("type_guid", Value::Str(g));
                x.set("thickness", Value::f(t));
            }
            if let (Some(a), Some(b)) = (common::point(x, "start"), common::point(x, "end")) {
                x.set("length", Value::f(((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt()));
            }
            if x.get("room_bounding").is_none() {
                x.set("room_bounding", Value::Bool(true));
            }
            if let Some(h) = crate::readers::slabs::attached_height(cx, id) {
                x.set("height", Value::f(h));
            }
        }
        "roomseparator" => {
            if let (Some(a), Some(b)) = (common::point(x, "start"), common::point(x, "end")) {
                x.set("length", Value::f(((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt()));
            }
        }
        _ => {}
    }
}
