//! Common lookups on the model: levels, elements by id or GUID.

use crate::json::Value;
use crate::project::Project;

/// Levels from the lowest up (ties by id).
pub fn levels(pr: &Project) -> Vec<u64> {
    crate::commands::basic::level_ids_sorted(pr)
}

pub fn elev(pr: &Project, level: u64) -> f64 {
    pr.el(level).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0)
}

pub fn name(pr: &Project, id: u64) -> String {
    pr.el(id).and_then(|e| e.get("name")).and_then(|x| x.as_str()).unwrap_or("").to_string()
}

/// The lowest level, where commands go without one.
pub fn default_level(pr: &Project) -> Option<u64> {
    levels(pr).first().copied()
}

/// The next level up from one, if any.
pub fn level_above(pr: &Project, level: u64) -> Option<u64> {
    let ls = levels(pr);
    let i = ls.iter().position(|l| *l == level)?;
    ls.get(i + 1).copied()
}

/// An element by its id (a number or a string of one) or its GUID.
pub fn find(pr: &Project, v: &Value) -> Option<u64> {
    match v {
        Value::Num(_) => {
            let id = crate::commands::params::id_of(v)?;
            if pr.elements.contains_key(&id) {
                Some(id)
            } else {
                None
            }
        }
        Value::Str(s) => {
            let t = s.trim();
            if let Ok(id) = t.parse::<u64>() {
                return if pr.elements.contains_key(&id) { Some(id) } else { None };
            }
            let g = normalize_guid(t)?;
            pr.find_guid(&g)
        }
        _ => None,
    }
}

/// A GUID as the model keeps it (lowercase, hyphenated), from one with or without braces and dashes.
pub fn normalize_guid(s: &str) -> Option<String> {
    let t = s.trim().trim_start_matches('{').trim_end_matches('}');
    let hex: String = t.chars().filter(|c| *c != '-').collect();
    if hex.len() != 32 || !hex.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    let h = hex.to_lowercase();
    Some(format!("{}-{}-{}-{}-{}", &h[0..8], &h[8..12], &h[12..16], &h[16..20], &h[20..32]))
}

/// A level (or a plan view, whose level it is) given by name, id or GUID.
pub fn resolve_level(pr: &Project, cmd: &str, key: &str, v: &Value) -> Result<u64, String> {
    let not = || format!("{}: `{}`: {} is not a level or a plan view", cmd, key, v.to_compact());
    match v {
        Value::Num(_) => {
            let id = find(pr, v).ok_or_else(not)?;
            level_of_view(pr, id).ok_or_else(not)
        }
        Value::Str(s) => {
            if let Some(id) = find(pr, v) {
                return level_of_view(pr, id).ok_or_else(not);
            }
            if s.trim().parse::<u64>().is_ok() || normalize_guid(s).is_some() {
                return Err(not());
            }
            for id in levels(pr) {
                if name(pr, id) == *s {
                    return Ok(id);
                }
            }
            for id in pr.ids_of("planview") {
                if name(pr, id) == *s {
                    if let Some(l) = level_of_view(pr, id) {
                        return Ok(l);
                    }
                }
            }
            let names: Vec<String> = levels(pr).iter().map(|l| name(pr, *l)).collect();
            Err(format!(
                "{}: no level or plan view named `{}` (the levels are: {})",
                cmd,
                s,
                names.join(", ")
            ))
        }
        _ => Err(not()),
    }
}

/// The level of a level, or of a plan view.
pub fn level_of_view(pr: &Project, id: u64) -> Option<u64> {
    match pr.category(id)? {
        "level" => Some(id),
        "planview" => {
            let g = pr.el(id)?.get("level")?.as_str()?.to_string();
            pr.find_guid(&g)
        }
        _ => None,
    }
}

/// A level from the params' `key`, else the lowest.
pub fn level_param(pr: &Project, cmd: &str, p: &Value, key: &str) -> Result<u64, String> {
    match crate::commands::params::get(p, key) {
        Some(v) => resolve_level(pr, cmd, key, v),
        None => default_level(pr).ok_or_else(|| format!("{}: the project has no level", cmd)),
    }
}

#!/usr/bin/env python3
"""Like cmp.py but pretty-prints JSON stdout lines before diffing, and shows more diff.
usage: jc.py [-f file]... [-n N] -- args...
"""
import os, re, subprocess, sys, tempfile, shutil, difflib, json
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/workspace/.claude/worktrees/agent-acefd841d6568a66c/target/release/bimcraft-cli')
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
def norm(s):
    s = re.sub(r'"uid": ?\d+', '"uid": <UID>', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m)+1)
        return m[g]
    s = GUID.sub(rep, s)
    s = re.sub(r"\.tmp[A-Za-z0-9]{6}", ".tmpXXXXXX", s)
    s = re.sub(r"'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d'", "'<TIMESTAMP>'", s)
    return s
def pretty(s):
    out = []
    for line in s.split('\n'):
        try:
            v = json.loads(line)
            out.append(json.dumps(v, indent=1, ensure_ascii=False))
        except Exception:
            out.append(line)
    return '\n'.join(out)
def run(exe, args, files, stdin):
    d = tempfile.mkdtemp(prefix='jc')
    for f in files: shutil.copy(f, d)
    p = subprocess.run([exe] + args, cwd=d, capture_output=True, input=stdin, timeout=300)
    out = {'stdout': p.stdout.decode('utf-8','replace'), 'stderr': p.stderr.decode('utf-8','replace'), 'code': p.returncode}
    fl = {}
    for root, dirs, fs in os.walk(d):
        for f in fs:
            full = os.path.join(root, f)
            rel = os.path.relpath(full, d)
            fl[rel] = open(full,'rb').read()
    shutil.rmtree(d)
    return out, fl
def main():
    a = sys.argv[1:]
    files = []; stdin = None; n = 80
    while a and a[0] != '--':
        if a[0] == '-f': files.append(a[1]); a = a[2:]
        elif a[0] == '-i': stdin = open(a[1],'rb').read(); a = a[2:]
        elif a[0] == '-n': n = int(a[1]); a = a[2:]
        else: break
    if a and a[0] == '--': a = a[1:]
    o, of = run(ORIG, a, files, stdin)
    m, mf = run(MINE, a, files, stdin)
    ok = True
    for k in ('code', 'stdout', 'stderr'):
        x = norm(pretty(str(o[k]))); y = norm(pretty(str(m[k])))
        if x != y:
            ok = False
            print(f'--- {k} differs')
            for l in list(difflib.unified_diff(x.splitlines(), y.splitlines(), 'orig', 'mine', lineterm='', n=2))[:n]:
                print(l[:300])
    names = [os.path.basename(x) for x in files]
    for f in sorted(set(of) | set(mf)):
        if f in names and of.get(f) == mf.get(f):
            continue
        if f not in of: ok = False; print(f'--- file {f} only in mine'); continue
        if f not in mf: ok = False; print(f'--- file {f} only in orig'); continue
        x, y = of[f], mf[f]
        try:
            xs = norm(x.decode('utf-8')); ys = norm(y.decode('utf-8'))
        except UnicodeDecodeError:
            if x != y: ok = False; print(f'--- binary file {f} differs ({len(x)} vs {len(y)} bytes)')
            continue
        if xs != ys:
            ok = False
            print(f'--- file {f} differs')
            for l in list(difflib.unified_diff(xs.splitlines(), ys.splitlines(), 'orig', 'mine', lineterm='', n=2))[:n]:
                print(l[:300])
    print('SAME' if ok else 'DIFF')
    sys.exit(0 if ok else 1)
main()
