#!/usr/bin/env python3
"""each.py [-f proj] [-p prefixcmd]... [-m] cmdsfile : run each line of cmdsfile as its own process (after prefix cmds); print last output or error."""
import sys, subprocess, os, json
a = sys.argv[1:]
proj = None; exe = '/workspace/executable'; pre = []; cwd = '/tmp/schedule-agent/w'; full = False
while a and a[0] in ('-f', '-p', '-m', '-F'):
