    a = a[2:]
lines = [l.rstrip('\n') for l in open(a[0]) if l.strip() and not l.startswith('#')]
for c in lines:
    args = [exe, 'run']
    if proj: args.append(proj)
    for x in pre: args += ['--cmd', x]
    args += ['--cmd', c]
