#!/usr/bin/env python3
"""save.py [-f proj] [-m] cmd... : run cmds, save, print outputs + schedule elements + next_id + history-ish."""
import sys, subprocess, os, json, tempfile
a = sys.argv[1:]
proj = None; exe = '/workspace/executable'
while a and a[0] in ('-f', '-m'):
    if a[0] == '-m':
        exe = '/workspace/.claude/worktrees/agent-a9628d0628a31203e/target/release/bimcraft-cli'; a = a[1:]; continue
    proj = a[1]; a = a[2:]
d = tempfile.mkdtemp(prefix='sv', dir='/tmp/schedule-agent/w')
out = os.path.join(d, 'out.bimcraft')
args = [exe, 'run']
if proj: args.append(proj)
for c in a: args += ['--cmd', c]
args += ['--cmd', 'undo {}', '--cmd', 'redo {}']
args += ['--save', out]
p = subprocess.run(args, capture_output=True, cwd=d)
print('code', p.returncode)
for line in p.stdout.decode().splitlines():
    print(line[:3000])
if p.stderr: print('STDERR:', p.stderr.decode())
if os.path.exists(out):
    dd = json.load(open(out))
    print('next_id', dd.get('next_id'))
    for k, e in dd['elements'].items():
        if e.get('category') == 'schedule':
            print(k, json.dumps(e, ensure_ascii=False))

