#!/usr/bin/env python3
"""csv.py [-f proj] [-m] [-p pre]... cmdsfile : run each line, show reply and the a.csv / a.xlsx written."""
import sys, subprocess, os, json, tempfile, shutil
a = sys.argv[1:]
proj = None; exe = '/workspace/executable'; pre = []
while a and a[0] in ('-f', '-m', '-p'):
    if a[0] == '-m':
        exe = '/workspace/.claude/worktrees/agent-a9628d0628a31203e/target/release/bimcraft-cli'; a = a[1:]; continue
    if a[0] == '-f': proj = a[1]
    else: pre.append(a[1])
    a = a[2:]
lines = [l.rstrip('\n') for l in open(a[0]) if l.strip() and not l.startswith('#')]
for c in lines:
    d = tempfile.mkdtemp(prefix='csv', dir='/tmp/schedule-agent/w')
    args = [exe, 'run']
    if proj: args.append(proj)
    for x in pre: args += ['--cmd', x]
    args += ['--cmd', c]
    p = subprocess.run(args, capture_output=True, cwd=d)
    print('>>', c)
    if p.returncode != 0:
        print('  ERR', p.stderr.decode().strip())
    else:
        print('  ', p.stdout.decode().splitlines()[-1][:1500])
    for f in sorted(os.listdir(d)):
        b = open(os.path.join(d, f), 'rb').read()
        print('  FILE', f, len(b))
        try:
            print(b.decode('utf-8'))
        except Exception:
            print(repr(b[:200]))
    shutil.rmtree(d)

