#!/usr/bin/env python3
"""xl.py [-f proj] [-m] [-p pre]... cmd : run, unzip the a.xlsx written and print its parts and zip structure."""
import sys, subprocess, os, json, tempfile, shutil, zipfile, struct
a = sys.argv[1:]
proj = None; exe = '/workspace/executable'; pre = []; keep = None
while a and a[0] in ('-f', '-m', '-p', '-k'):
    if a[0] == '-m':
        exe = '/workspace/.claude/worktrees/agent-a9628d0628a31203e/target/release/bimcraft-cli'; a = a[1:]; continue
    if a[0] == '-f': proj = a[1]
    elif a[0] == '-k': keep = a[1]
    else: pre.append(a[1])
    a = a[2:]
d = tempfile.mkdtemp(prefix='xl', dir='/tmp/schedule-agent/w')
args = [exe, 'run']
if proj: args.append(proj)
for x in pre: args += ['--cmd', x]
for c in a: args += ['--cmd', c]
p = subprocess.run(args, capture_output=True, cwd=d)
print(p.returncode, p.stdout.decode()[-600:], p.stderr.decode())
for f in sorted(os.listdir(d)):
    path = os.path.join(d, f)
    b = open(path, 'rb').read()
    print('FILE', f, len(b))
    if keep: shutil.copy(path, keep)
    if f.endswith('.xlsx'):
        z = zipfile.ZipFile(path)
        for i in z.infolist():
            print('--', i.filename, i.compress_type, i.date_time, i.file_size, i.compress_size, hex(i.CRC), i.flag_bits, i.create_version, i.extract_version, i.external_attr, i.create_system, repr(i.extra), repr(i.comment))
            print(z.read(i.filename).decode('utf-8'))
    elif f.endswith('.csv'):
        print(b.decode())
shutil.rmtree(d)

