    c.out.out
}

/// A zlib stream of `data` (header `78 01`), as flate2 writes it at `Compression::fast()`.
pub fn zlib_compress(data: &[u8]) -> Vec<u8> {
    compress(data, true, 1)
}

/// Raw deflate of `data`, as flate2's `DeflateEncoder` writes it at `Compression::fast()`.
pub fn deflate_compress(data: &[u8]) -> Vec<u8> {
    compress(data, false, 1)
}

/// A zlib stream of `data` at a flate2 level (0 stored, 1 fast, 6 `Compression::default()`, 9 best;
/// written whole with `write_all`, then `finish`).
pub fn zlib_compress_level(data: &[u8], level: u32) -> Vec<u8> {
    compress(data, true, level)
}

/// Raw deflate of `data` at a flate2 level.
pub fn deflate_compress_level(data: &[u8], level: u32) -> Vec<u8> {
    compress(data, false, level)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn hex(s: &str) -> Vec<u8> {
        (0..s.len() / 2).map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap()).collect()
    }

    #[test]
    fn as_the_original_packs_a_small_scan() {
        // le.ply's points, as BIMCraft 0.10 packed them into a project file
        let mut pts = Vec::new();
        for v in [-50000.0f32, 1000.0, -3500.0, -48500.0, -1000.0, -250.0, 50000.0, 1000.0, 3500.0] {
            pts.extend_from_slice(&v.to_le_bytes());
        }
        let want = hex("78016308703ecec050e5c27020ea2843892d887d04c83f0c147707d220715700ca600ae2");
        assert_eq!(zlib_compress(&pts), want);
        assert_eq!(zlib_compress(&[255, 0, 0, 10, 20, 30, 0, 0, 255]), hex("7801fbcfc0c02522c7c0f01f000b17023b"));
    }

    #[test]
    fn round_trips_at_every_level() {
        let mut data = Vec::new();
        let mut x: u32 = 12345;
        for i in 0..200_000u32 {
            x = x.wrapping_mul(1103515245).wrapping_add(12345);
            data.push(if i % 7 == 0 { (x >> 24) as u8 } else { (i % 251) as u8 });
        }
        for level in 0..=10 {
            let z = zlib_compress_level(&data, level);
            assert_eq!(crate::inflate::zlib_decode(&z, data.len()).unwrap(), data, "level {}", level);
        }
        assert_eq!(zlib_compress(&[]), vec![0x78, 0x01, 0x03, 0x00, 0x00, 0x00, 0x00, 0x01]);
    }
}
//! A JSON value with insertion-ordered objects, a parser whose errors read as
//! serde_json's do, and writers (compact, pretty, key-sorted) that format numbers
//! the way serde_json does (integers as integers, floats in shortest form).

use std::fmt::Write as _;

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Num(Num),
    Str(String),
    Arr(Vec<Value>),
    Obj(Map),
}

impl Default for Value {
    fn default() -> Value {
        Value::Null
    }
}

#[derive(Clone, Copy, Debug)]
pub enum Num {
    U(u64),
    I(i64),
    F(f64),
}

impl PartialEq for Num {
    fn eq(&self, other: &Num) -> bool {
        match (self, other) {
            (Num::U(a), Num::U(b)) => a == b,
            (Num::I(a), Num::I(b)) => a == b,
            (Num::F(a), Num::F(b)) => a == b,
            _ => false,
        }
    }
}

impl Num {
    pub fn as_f64(&self) -> f64 {
        match *self {
            Num::U(u) => u as f64,
            Num::I(i) => i as f64,
            Num::F(f) => f,
        }
    }
}

/// An object: keys in insertion order.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Map {
    pub items: Vec<(String, Value)>,
}

impl Map {
    pub fn new() -> Map {
        Map { items: Vec::new() }
    }
    pub fn get(&self, k: &str) -> Option<&Value> {
        self.items.iter().find(|(kk, _)| kk == k).map(|(_, v)| v)
    }
    pub fn get_mut(&mut self, k: &str) -> Option<&mut Value> {
        self.items.iter_mut().find(|(kk, _)| kk == k).map(|(_, v)| v)
    }
    pub fn contains(&self, k: &str) -> bool {
        self.items.iter().any(|(kk, _)| kk == k)
    }
    /// Sets a key, keeping its place if it is there, else appending it.
    pub fn insert(&mut self, k: &str, v: Value) {
        if let Some(slot) = self.get_mut(k) {
            *slot = v;
        } else {
            self.items.push((k.to_string(), v));
        }
    }
    /// Sets a key in sorted (byte) order, as a BTreeMap would hold it.
    pub fn insert_sorted(&mut self, k: &str, v: Value) {
        match self.items.binary_search_by(|(kk, _)| kk.as_str().cmp(k)) {
            Ok(i) => self.items[i].1 = v,
            Err(i) => self.items.insert(i, (k.to_string(), v)),
        }
    }
    pub fn remove(&mut self, k: &str) -> Option<Value> {
        let i = self.items.iter().position(|(kk, _)| kk == k)?;
        Some(self.items.remove(i).1)
    }
    pub fn len(&self) -> usize {
        self.items.len()
    }
    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
    pub fn keys(&self) -> impl Iterator<Item = &String> {
        self.items.iter().map(|(k, _)| k)
    }
    pub fn iter(&self) -> impl Iterator<Item = (&String, &Value)> {
        self.items.iter().map(|(k, v)| (k, v))
    }
    pub fn sort(&mut self) {
        self.items.sort_by(|a, b| a.0.cmp(&b.0));
    }
}

impl Value {
    pub fn obj() -> Value {
        Value::Obj(Map::new())
    }
    pub fn f(x: f64) -> Value {
        Value::Num(Num::F(x))
    }
    pub fn u(x: u64) -> Value {
        Value::Num(Num::U(x))
    }
    pub fn i(x: i64) -> Value {
        if x >= 0 {
            Value::Num(Num::U(x as u64))
        } else {
            Value::Num(Num::I(x))
        }
    }
    pub fn s(x: &str) -> Value {
        Value::Str(x.to_string())
    }
    pub fn is_null(&self) -> bool {
        matches!(self, Value::Null)
    }
    pub fn as_f64(&self) -> Option<f64> {
        match self {

                if ed.starts_with(&half) && ed[half.len()..].bytes().all(|b| b == b'0') {
                    let back: Option<f64> = format!("{}.{}e{}", &alt[..1], &alt[1..], exp).parse().ok();
                    if back == Some(x.abs()) {
                        digits = alt;
                    }
                }
            }
        }
    }
    // mant = d.ddd, so value = d.ddd * 10^exp = 0.dddd * 10^(exp+1)
    (digits, exp + 1)
}

/// Formats an f64 as serde_json (ryu) does.
pub fn fmt_f64(x: f64) -> String {
    if !x.is_finite() {
        return "null".to_string();
    }
    let mut out = String::new();
    if x.is_sign_negative() {
        out.push('-');
    }
    if x == 0.0 {
        out.push_str("0.0");
        return out;
    }
    let (digits, kk) = shortest_digits(x);
    let length = digits.len() as i32;
    let k = kk - length;
    if 0 <= k && kk <= 16 {
        out.push_str(&digits);
        for _ in length..kk {
            out.push('0');
        }
        out.push_str(".0");
    } else if 0 < kk && kk <= 16 {
        out.push_str(&digits[..kk as usize]);
        out.push('.');
        out.push_str(&digits[kk as usize..]);
    } else if -5 < kk && kk <= 0 {
        out.push_str("0.");
        for _ in 0..(-kk) {
            out.push('0');
        }
        out.push_str(&digits);
    } else {
        out.push_str(&digits[..1]);
        if length > 1 {
            out.push('.');
            out.push_str(&digits[1..]);
        }
        out.push('e');
        if kk - 1 > 0 {
            out.push('+');
        }
        let _ = write!(out, "{}", kk - 1);
    }
    out
}

/// How serde's "invalid type" message shows a float (Rust's Display, with a `.0` for integers).
pub fn fmt_f64_display(x: f64) -> String {
    if x.is_finite() && x == x.trunc() && x.abs() < 1e16 {
        format!("{}.0", x as i64)
    } else {
        format!("{}", x)
    }
}

fn write_num(n: &Num, out: &mut String) {
    match n {
        Num::U(u) => {
            let _ = write!(out, "{}", u);
        }
        Num::I(i) => {
            let _ = write!(out, "{}", i);
        }
        Num::F(f) => out.push_str(&fmt_f64(*f)),
    }
}

pub fn write_str(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                let _ = write!(out, "\\u{:04x}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

pub fn write_compact(v: &Value, out: &mut String) {
    match v {
        Value::Null => out.push_str("null"),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Num(n) => write_num(n, out),
        Value::Str(s) => write_str(s, out),
        Value::Arr(a) => {
            out.push('[');
            for (i, x) in a.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_compact(x, out);
            }
            out.push(']');
        }
        Value::Obj(m) => {
            out.push('{');
            for (i, (k, x)) in m.items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_str(k, out);
                out.push(':');
                write_compact(x, out);
            }
            out.push('}');
        }
    }
}

fn indent(out: &mut String, n: usize) {
    for _ in 0..n {
        out.push_str("  ");
    }
}

pub fn write_pretty(v: &Value, out: &mut String, level: usize) {
    match v {
        Value::Arr(a) => {
            if a.is_empty() {
